parameters.jsCode:
// A booking the caller believes they have and the clinic has never heard of
// is the most damaging failure this system can produce, so it gets its own
// workflow rather than a catch block.
//
// Envelope contract (fire-and-forget POST from the book_appointment tool's
// failure paths): { callId?, phone, locationId?, code, retryable,
// agentShouldSay, offeredSlotId? }

const body = $input.first().json;
const str = (v) => (v === undefined || v === null ? '' : String(v).trim());

const phone = str(body.phone || body.from_phone || '').replace(/[^+0-9]/g, '');
const location_id = str(body.locationId || body.location_id);

return [{
  json: {
    call_id: str(body.callId || body.call_id),
    phone,
    has_phone: phone.length >= 7,
    location_id: location_id || null,
    code: str(body.code || 'booking_failed'),
    retryable: body.retryable === true || body.retryable === 'true',
    agent_should_say: str(body.agentShouldSay || body.agent_should_say),
    slot_id: str(body.offeredSlotId || body.slot_id),
    raw_code: str(body.reason || body.error || '')
  }
}];

