-- The front desk queue (messages) is where a human will actually see it;
-- Slack is the noisy nudge. The summary carries everything needed to call
-- the patient back without opening the console.
INSERT INTO messages (call_id, location_id, contact_phone, contact_name, summary, callback_window)
VALUES (NULLIF($1, ''), $2, $3, NULL, $4, 'asap');
